import { test, expect } from '@playwright/test';

test.describe('Mark All Notifications as Read', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should mark all notifications as read with a single click', async ({ page }) => {
    // Verify notifications are visible
    const notificationItems = page.getByRole('region', { name: /notification/i });
    await expect(notificationItems).toBeVisible();

    // Verify unread count is displayed
    const unreadCount = page.getByText('3');
    await expect(unreadCount).toBeVisible();

    // Verify "Mark All as Read" button is visible and enabled
    const markAllButton = page.getByRole('button', { name: /mark all as read/i });
    await expect(markAllButton).toBeVisible();
    await expect(markAllButton).not.toBeDisabled();

    // Click the "Mark All as Read" button
    await markAllButton.click();

    // Verify success message appears
    const successMessage = page.getByText('All notifications marked as read');
    await expect(successMessage).toBeVisible();

    // Verify unread count is updated to 0
    const updatedUnreadCount = page.getByText('0');
    await expect(updatedUnreadCount).toBeVisible();

    // Verify notification items are no longer marked as unread
    const notificationItemsAfter = page.getByRole('region', { name: /notification/i });
    await expect(notificationItemsAfter).toHaveCount(3);

    // Verify each notification item has the read status indicator
    const notificationReadIndicators = page.getByRole('status', { name: /read/i });
    await expect(notificationReadIndicators).toHaveCount(3);
  });

  test('should handle case with no notifications', async ({ page }) => {
    // Navigate to notifications page
    await page.goto('/notifications');

    // Verify "No notifications" message is displayed
    const noNotificationsMessage = page.getByText('No notifications');
    await expect(noNotificationsMessage).toBeVisible();

    // Verify "Mark All as Read" button is not visible
    const markAllButton = page.getByRole('button', { name: /mark all as read/i });
    await expect(markAllButton).not.toBeVisible();

    // Verify unread count is 0
    const unreadCount = page.getByText('0');
    await expect(unreadCount).toBeVisible();

    // Verify empty state is displayed
    const emptyState = page.getByRole('status', { name: /empty/i });
    await expect(emptyState).toBeVisible();
  });
});
